#[derive(Debug, Default)]
pub(crate) struct StaticBuiltinModelBasePriceCatalog;

impl BuiltinModelBasePriceCatalog for StaticBuiltinModelBasePriceCatalog {
    fn model_base_prices(&self) -> Vec<UpsertModelBasePriceInput> {
        BUILTIN_MODEL_BASE_PRICES
            .iter()
            .map(|price| UpsertModelBasePriceInput {
                id: Some(price.id.to_string()),
                provider: price.provider.to_string(),
                model: price.model.to_string(),
                input_price: price.input_price,
                output_price: price.output_price,
                input_price_priority: None,
                output_price_priority: None,
                cache_creation_price: price.cache_creation_price,
                cache_creation_price_priority: None,
                cache_creation_price_above_1hr: None,
                cache_read_price: price.cache_read_price,
                cache_read_price_priority: None,
                long_context_input_token_threshold: None,
                long_context_input_cost_multiplier: None,
                long_context_output_cost_multiplier: None,
                supports_service_tier: false,
                supports_prompt_caching: price.cache_creation_price.is_some() || price.cache_read_price.is_some(),
                currency: "USD".to_string(),
                unit: "M".to_string(),
                source_url: "https://github.com/farion1231/cc-switch/blob/9a596158ca926e74b56243c08af67d9dd13fc27c/src-tauri/src/database/schema.rs".to_string(),
                source_label: "CC Switch built-in model pricing".to_string(),
                source_checked_at: Some(BUILTIN_MODEL_BASE_PRICE_CHECKED_AT.to_string()),
                enabled: true,
                built_in: true,
                note: Some(format!("{}; USD per M tokens; adapted from CC Switch.", price.display_name)),
            })
            .collect()
    }
}
